window.ScripturaLexicons.BDAG_PART_0307 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0307-01\" data-source=\"BDAG\" data-search=\"πρόσοψις, εως, ἡ substantivo feminino aparência, aspecto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πρόσοψις, εως, ἡ</td><td>substantivo feminino</td><td>aparência, aspecto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0307-02\" data-source=\"BDAG\" data-search=\"προσπαίω verbo bater, golpear contra BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προσπαίω</td><td>verbo</td><td>bater, golpear contra</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0307-03\" data-source=\"BDAG\" data-search=\"πρόσπεινος, ον adjetivo faminto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πρόσπεινος, ον</td><td>adjetivo</td><td>faminto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0307-04\" data-source=\"BDAG\" data-search=\"προσπήγνυμι verbo fixar, prender, pregar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προσπήγνυμι</td><td>verbo</td><td>fixar, prender, pregar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0307-05\" data-source=\"BDAG\" data-search=\"προσπίπτω verbo prostrar-se, cair sobre, bater contra BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προσπίπτω</td><td>verbo</td><td>prostrar-se, cair sobre, bater contra</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0307-06\" data-source=\"BDAG\" data-search=\"προσποιέω verbo fingir, fazer como se, dar atenção BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προσποιέω</td><td>verbo</td><td>fingir, fazer como se, dar atenção</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0307-07\" data-source=\"BDAG\" data-search=\"προσπορεύομαι verbo depoente aproximar-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προσπορεύομαι</td><td>verbo depoente</td><td>aproximar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0307-08\" data-source=\"BDAG\" data-search=\"προσρήγνυμι verbo remissão a προσρήσσω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προσρήγνυμι</td><td>verbo</td><td>remissão a προσρήσσω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0307-09\" data-source=\"BDAG\" data-search=\"προσρήσσω verbo despedaçar, quebrar, irromper contra BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προσρήσσω</td><td>verbo</td><td>despedaçar, quebrar, irromper contra</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0307-10\" data-source=\"BDAG\" data-search=\"πρόσταγμα, ατος, τό substantivo neutro ordem, mandamento, determinação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πρόσταγμα, ατος, τό</td><td>substantivo neutro</td><td>ordem, mandamento, determinação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0307-11\" data-source=\"BDAG\" data-search=\"προστάσσω verbo ordenar, prescrever, determinar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προστάσσω</td><td>verbo</td><td>ordenar, prescrever, determinar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0307-12\" data-source=\"BDAG\" data-search=\"προστάτης, ου, ὁ substantivo masculino defensor, guardião, benfeitor BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προστάτης, ου, ὁ</td><td>substantivo masculino</td><td>defensor, guardião, benfeitor</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0307-13\" data-source=\"BDAG\" data-search=\"προστάτις, ιδος, ἡ substantivo feminino protetora, patrona, benfeitora BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προστάτις, ιδος, ἡ</td><td>substantivo feminino</td><td>protetora, patrona, benfeitora</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0307-14\" data-source=\"BDAG\" data-search=\"προστίθημι verbo acrescentar, juntar, conceder BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προστίθημι</td><td>verbo</td><td>acrescentar, juntar, conceder</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0307-15\" data-source=\"BDAG\" data-search=\"πρόστιμον, ου, τό substantivo neutro pena, penalidade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πρόστιμον, ου, τό</td><td>substantivo neutro</td><td>pena, penalidade</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0307-16\" data-source=\"BDAG\" data-search=\"προστρέχω verbo correr para, aproximar-se correndo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προστρέχω</td><td>verbo</td><td>correr para, aproximar-se correndo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0307-17\" data-source=\"BDAG\" data-search=\"προσφάγιον, ου, τό substantivo neutro peixe para comer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προσφάγιον, ου, τό</td><td>substantivo neutro</td><td>peixe para comer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0307-18\" data-source=\"BDAG\" data-search=\"πρόσφατος, ον adjetivo novo, recente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πρόσφατος, ον</td><td>adjetivo</td><td>novo, recente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0307-19\" data-source=\"BDAG\" data-search=\"προσφάτως advérbio recentemente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προσφάτως</td><td>advérbio</td><td>recentemente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0307-20\" data-source=\"BDAG\" data-search=\"προσφέρω verbo trazer, apresentar, oferecer, tratar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προσφέρω</td><td>verbo</td><td>trazer, apresentar, oferecer, tratar</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0307-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρόσοψις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πρόσοψις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> aparência, aspecto (assim em sentido pass. Pind. et al.; Polyb. 9, 41, 2; Diod S 1, 91, 6; 13, 27, 6; Lucian, Tim. 41; Kaibel 376, 8; LXX; EpArist 59) Hs 9, 1, 10.—DELG s.v. <span class=\"greek\">ὄπωπα</span> D.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0307-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσπαίω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προσπαίω</span> 1.º aor. <span class=\"greek\">προσέπαισα</span> (Soph., Fgm. 311 [335 Pearson]; escólio sobre Aeschyl., Prom. 885; Ps. 90, 12 Sym.) bater, golpear contra <span class=\"greek\">τινί</span> algo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:25</a> conj. de Lachmann em lugar de <span class=\"greek\">προσέπεσαν</span>; favorecida por SNaber, Mnemosyne 9, 1881, 276 e EbNestle, ZNW 9, 1908, 252f. B-D-F §202.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0307-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρόσπεινος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πρόσπεινος</span>, <span class=\"greek\">ον</span> (<span class=\"greek\">πεῖνα</span> ‘fome’; Demosthenes Ophthalmicus [I d.C.] em Aëtius p. 74, 26 <span class=\"greek\">εἰ</span> <span class=\"greek\">πρόσπεινοι</span> <span class=\"greek\">γένωνται</span>) com fome <span class=\"greek\">πρόσπεινον</span> <span class=\"greek\">γενέσθαι</span> ficar com fome <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:10</a>.—DELG s.v. <span class=\"greek\">πείνη</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0307-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσπήγνυμι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προσπήγνυμι</span> 1.º aor. <span class=\"greek\">προσέπηξα</span> (Eur., Fgm. 679 Nauck2; Philo Mech. 74, 10; Cass. Dio 40, 9; 63, 2) fixar/prender a, em uso absoluto, pregar a (uma cruz) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:23</a>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0307-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσπίπτω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προσπίπτω</span> imperf. <span class=\"greek\">προσέπιπτον</span>; aor. <span class=\"greek\">προσέπεσον</span> ou <span class=\"greek\">προσέπεσα</span>—B-D-F §81, 3; Mlt-H. 208 (Hom.+; pap, LXX; TestAbr A; ApcMos; EpArist 180; Philo, Joseph.).</p><p class=\"entry-text\">① prostrar-se diante de alguém, cair diante de/aos pés de, frequentemente no gesto de um suplicante (Soph. et al.), com dat. de pessoa (Pla., Ep. 7, 349a; Polyb. 10, 18, 7; Plut., Pyrrh. 384 [3, 4]; PPetr II, 1, 4 [III a.C.]; Ps 94:6; Jos., Bell. 3, 201; 454) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:11</a>; 5:33; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:28</a>, 47; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:29</a>; GEb 18, 39.—Diante de Deus <span class=\"greek\">τῷ</span> <span class=\"greek\">δεσπότῃ</span> 1 Cl 48:1; uso absoluto 9:1 (cf. TestAbr A 14 p. 94, 14f [Stone p. 36] <span class=\"greek\">τοῖς</span> <span class=\"greek\">οἰκτιρμοῖς</span> <span class=\"greek\">αὐτοῦ</span>; ApcMos 33 <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῶ</span>.).—<span class=\"greek\">πρ</span>. <span class=\"greek\">τοῖς</span> <span class=\"greek\">γόνασίν</span> <span class=\"greek\">τινος</span> cair aos pés de alguém (Eur., Or. 1332 al.; Plut., Pomp. 621 [5, 2], Mor. 1117b; Chariton 3, 2, 1; Achilles Tat. 5, 17, 3; Jos., Ant. 19, 234. V. TestAbr A 3 p. 79, 28 [Stone p. 6] al. <span class=\"greek\">τοῖς</span> <span class=\"greek\">ποσὶν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀσωμάτου</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:8</a>, a menos que aqui se faça referência ao ato de um suplicante agarrar os joelhos de uma pessoa, como talvez na passagem de Eur. acima (v. L-S-J-M s.v. <span class=\"greek\">γόνυ</span> 1 e <span class=\"greek\">προσπίπτω</span> III). <span class=\"greek\">πρὸς</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">πόδας</span> <span class=\"greek\">τινός</span> (Esth 8:3; cf. Ex 4:25 e PCairZen 210, 1 [254 a.C.] <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">γόνατα</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:25</a>.</p><p class=\"entry-text\">② mover-se com força contra algo, cair sobre, bater contra (cf. Thu. 3, 103, 2 et al.; Appian, Bell. Civ. 4, 113 §472; Arrian, Anab. 3, 13, 6; Sir 25:21; Pr 25:20; Jos., Bell. 4, 343) <span class=\"greek\">τινί</span> algo, dos ventos (Ael. Aristid. 36, 8 K.=48 p. 440 D.; escólio sobre Apollon. Rhod. 4, 26–71a p. 277, 6) que batem contra uma casa com grande força <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:25</a> (v. <span class=\"greek\">προσπαίω</span> e <span class=\"greek\">προσκόπτω</span> 2).—Sobrevir (repentinamente) <span class=\"greek\">ὀξυχολία</span> <span class=\"greek\">προσπίπτει</span> <span class=\"greek\">τινί</span> o mau humor apodera-se de alguém Hm 6, 2, 5 (Menand., Epitr. 497 J. <span class=\"greek\">χολὴ</span> <span class=\"greek\">μέλαινα</span> <span class=\"greek\">πρ</span>.).—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0307-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσποιέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προσποιέω</span> 2.ª sg. méd. <span class=\"greek\">προσποιεῖ</span> (sobre esta forma ática v. Schwyzer I 668; Rob. 339f; B-D-F §27; cf. <span class=\"greek\">βούλει</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:42</a>) 1.º aor. méd. <span class=\"greek\">προσεποιησάμην</span> (Eur., Hdt.+; pap, LXX, Test12Patr) em nossa literatura somente na voz média.</p><p class=\"entry-text\">① realizar ação ou gesto que dá a impressão de expressar determinada intenção, fazer/agir como se, fingir (Thu., Pla. et al.; Diod S 1, 94, 1; 15, 46, 2; Plut., Timol. 238 [5, 2]; Aelian, VH 8, 5; PCairZen 534, 44; 61 [III a.C.]; Philo, In Flacc. 40; 98; Jos., C. Ap. 1, 5, Vi. 319; TestJud 7:2) seguido de inf. (assim na maioria das passagens citadas, também Jos., Ant. 13, 102; TestJos 3:7) <span class=\"greek\">προσεποιήσατο</span> <span class=\"greek\">πορρώτερον</span> <span class=\"greek\">πορεύεσθαι</span> fez como se fosse mais adiante <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:28</a>. <span class=\"greek\">προσποιεῖ</span> <span class=\"greek\">ἀγνοεῖν</span> <span class=\"greek\">με</span> finges não me conhecer MPol 10:1.</p><p class=\"entry-text\">② agir em resposta a, dar atenção (a), em uso absoluto (Zenão de Eleia em Diog. L. 9, 29 <span class=\"greek\">ἐὰν</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">προσποιῶμαι</span>=se eu não der atenção [a isso].—A coisa à qual se dá atenção é acrescentada no acus.: Diog. L. 1, 20 <span class=\"greek\">τὶ</span>; Job 19:14 <span class=\"greek\">με</span>.) <span class=\"greek\">μὴ</span> <span class=\"greek\">προσποιούμενος</span> sem dar atenção <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.6\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:6</a> v.l.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0307-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσπορεύομαι</h1><div class=\"entry-meta\"><span>verbo depoente</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προσπορεύομαι</span> depoente (Aristot., Polyb.; SIG 344, 112; PEleph 18, 5 [223/222 a.C.]; PMagd 27, 6; PAmh 33, 17; UPZ 79, 3 [159 a.C.] <span class=\"greek\">προσπορεύεταί</span> <span class=\"greek\">μοι</span>; LXX) chegar junto de, aproximar-se <span class=\"greek\">τινί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:35</a>.—JLee, Equivocal and Stereotyped Renderings in the LXX: RB 87, ’80, 104–17. DELG s.v. <span class=\"greek\">πόρος</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0307-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσρήγνυμι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προσρήγνυμι</span> v. <span class=\"greek\">προσρήσσω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0307-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσρήσσω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προσρήσσω</span> (sobre a relação entre <span class=\"greek\">ῥήσσω</span> e <span class=\"greek\">ῥήγνυμι</span> v. EFraenkel, Gesch. der griech. Nomina agentis II 1912, 40f; B-D-F §101 sob <span class=\"greek\">ῥηγνύναι</span>; Mlt-H. 403) fut. 2.ª sg. <span class=\"greek\">προσρήξεις</span> (Ps. 2:9 Aq); 1.º aor. <span class=\"greek\">προσέρηξα</span> (sobre a forma com -<span class=\"greek\">ρρ</span>- v. W-S. §5, 26b; Mlt-H. 193).</p><p class=\"entry-text\">① quebrar em pedaços ao bater contra algo, despedaçar, estilhaçar, trans. (Ps 2:9 Aq; Jos., Ant. 6, 182; 9, 91) pass. (escólio sobre Soph., Trach. 821 Papag.) com dat. de coisa: ser despedaçado ou destruído ao chocar-se com algo (M. Ant. 4, 49, 1 <span class=\"greek\">ἄκρᾳ</span>, <span class=\"greek\">ᾗ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">κύματα</span> <span class=\"greek\">προσρήσσεται</span>; Etym. Mag. p. 703, 20 <span class=\"greek\">προσρησσομένου</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">γῇ</span> <span class=\"greek\">ὕδατος</span>; Ar. 16, 6 <span class=\"greek\">προσρήσσονται</span> <span class=\"greek\">ἑαυτοῖς</span>) <span class=\"greek\">ἵνα</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">προσρησσώμεθα</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἐκείνων</span> <span class=\"greek\">νόμῳ</span> para que não nos destrocemos contra a lei deles B 3:6.</p><p class=\"entry-text\">② romper com força contra, irromper sobre, intr., com dat. de coisa <span class=\"greek\">προσέρηξεν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ποταμὸς</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">οἰκίᾳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.48\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:48</a>; cf. v. 49; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:27</a> v.l.—M-M s.v. <span class=\"greek\">προσρήγυμι</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0307-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρόσταγμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πρόσταγμα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">προστάσσω</span>; Pla.+; empréstimo na literatura rabínica) diretriz oficial, ordem, mandamento, determinação (SEG XXXVII, 10 [209 a.C.]), em nossa literatura somente de preceitos divinos (<span class=\"greek\">πρόσταγμα</span> de mandamento divino: Dio Chrys. 16 [33], 9; Ael. Aristid. 48, 51 K.=24 p. 478 D.; Ptolem., Apotel. 1, 3, 6 <span class=\"greek\">θεῖον</span> <span class=\"greek\">πρ</span>.; SIG 1127, 8; 1129; 1131; 1138; IG XI, 1263; PEdg 7 [=Sb 6713], 19 [257 a.C.] <span class=\"greek\">τὰ</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">προστάγματα</span>; Sb 685 [II a.C.] <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">πρόσταγμα</span> <span class=\"greek\">ἔχων</span>; UPZ 20, 27; PGM 5, 138; 13, 268; LXX; En 18:15; EpArist 279; Philo; Jos., C. Ap. 2, 231 <span class=\"greek\">τὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">νόμου</span> <span class=\"greek\">πρ</span>., Ant. 2, 291 <span class=\"greek\">θεοῦ</span> <span class=\"greek\">πρ</span>.; Ar. 4, 1; Just., D. 122, 5) Dg 12:5. Nos demais lugares sempre pl. 1 Cl 20:5. <span class=\"greek\">τὰ</span> <span class=\"greek\">ἄμωμα</span> <span class=\"greek\">πρ</span>. <span class=\"greek\">αὐτοῦ</span> 37:1; <span class=\"greek\">τὰ</span> <span class=\"greek\">λαϊκὰ</span> <span class=\"greek\">πρ</span>. normas para os que não exercem funções litúrgicas 40:5. Com <span class=\"greek\">δικαιώματα</span> 2:8; 58:2. <span class=\"greek\">τὰ</span> <span class=\"greek\">πρ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ποιεῖν</span> guardar os mandamentos de Deus 50:5. <span class=\"greek\">πορεύεσθαι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">πρ</span>. <span class=\"greek\">αὐτοῦ</span> Hs 5, 1, 5. <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">νομίμοις</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">προσταγμάτων</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">πορεύεσθαι</span> andar segundo as leis de seus mandamentos 1 Cl 3:4. <span class=\"greek\">ὑπακούειν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">πρ</span>. obedecer às instruções 2 Cl 19:3.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0307-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προστάσσω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προστάσσω</span> fut. 3.ª sg. <span class=\"greek\">προστάξει</span> Lev. 14:4 al.; 1.º aor. <span class=\"greek\">προσέταξα</span>; perf. <span class=\"greek\">προστέταχα</span> LXX; mais-que-perf. 3.ª sg. <span class=\"greek\">προσετετάχει</span> (Just., D. 21, 1). Pass.: 1.º aor. <span class=\"greek\">προσετάχθην</span>; 2.º aor. <span class=\"greek\">προσετάγην</span>; perf. <span class=\"greek\">προστέταγμαι</span>, part. <span class=\"greek\">προστεταγμένος</span> (v. <span class=\"greek\">πρόσταγμα</span>; Aeschyl., Hdt.+) emitir uma diretriz oficial ou tomar uma determinação, mandar, ordenar, dar instruções, determinar, com dat. de pessoa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:24</a>; 21:6 v.l. (em lugar de <span class=\"greek\">συνέταξεν</span>); AcPl Ha 5, 36. Com acus. de coisa: ordenar, prescrever algo (Herodas 6, 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.44\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:44</a>; PtK 4 p. 16, 5. <span class=\"greek\">πρ</span>. <span class=\"greek\">τὰ</span> <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span> dar ordens a respeito de alguém Hs 7:1. <span class=\"greek\">τινί</span> <span class=\"greek\">τι</span> pass. <span class=\"greek\">τὰ</span> <span class=\"greek\">προστεταγμένα</span> <span class=\"greek\">σοι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.33\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:33</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">προσταχθὲν</span> <span class=\"greek\">ἡμῖν</span> GMary Ox 3525, 27 (cf. OGI 664, 15 <span class=\"greek\">τὰ</span> <span class=\"greek\">ὑπ</span>’ <span class=\"greek\">ἐμοῦ</span> <span class=\"greek\">προσταχθέντα</span>; ParJer 6:9 <span class=\"greek\">τὰ</span> <span class=\"greek\">προσταχθένται</span> <span class=\"greek\">σου</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀγγέλων</span>). <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἱερεῦσιν</span> <span class=\"greek\">τόπος</span> <span class=\"greek\">προστέτακται</span> uma função é atribuída aos sacerdotes 1 Cl 40:5. Sem o dat. <span class=\"greek\">ἵνα</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">κατέξω</span> <span class=\"greek\">τὰ</span> [<span class=\"greek\">πρός</span>]<span class=\"greek\">τεταγμένα</span> para que eu não impeça aquilo que me foi determinado AcPl Ha 7, 14. Seguido de acus. e inf. (Eur., X.; PTebt 7, 1; 1 Esdr 8:10; 3 Macc 7:8; TestAbr B 2 p. 106, 5 [Stone p. 60, 5]; Philo, Spec. Leg. 2, 130; Jos., Ant. 10, 213) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.48\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:48</a>; 1 Cl 20:11. Pass., seguido de inf. (Jos., Bell. 1, 488; Just., D. 19, 6; Tat. 4, 1) Hm 4, 1, 10. <span class=\"greek\">ποιεῖν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">προστασσόμενα</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πλήθους</span> 1 Cl 54:2. Uso absoluto <span class=\"greek\">καθὼς</span> <span class=\"greek\">προσέταξεν</span> (TestAbr A 20 p. 103, 2 [Stone p. 54]; cf. Gen 47:11; TestBenj 12:3 [ms. c, v. Charles]; Jos., Ant. 8, 267) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:14</a>; Hs 7:5; cf. IPol 8:1. (<span class=\"greek\">οἱ</span>) <span class=\"greek\">προστεταγμένοι</span> <span class=\"greek\">καιροί</span> (os) tempos fixados <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:26</a>; 1 Cl 40:4 (<span class=\"greek\">καιρός</span> 2, final.—Jos., Ant. 3, 30 <span class=\"greek\">τὸ</span> <span class=\"greek\">προστεταγμένον</span> <span class=\"greek\">μέτρον</span>).—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0307-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προστάτης, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προστάτης</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (cf. <span class=\"greek\">προστάτις</span>; Aeschyl., Hdt.+; Eupolis, CGFP 96, 63–66 [duas vezes, ambas reconstituídas]; ins, pap, LXX; ApcSed 14, 1 p. 135, 34 Ja.; EpArist 111; Jos., Bell. 1, 385; Just., D. 92, 2. Primariamente: daquele que ‘se coloca à frente’ [<span class=\"greek\">προί̈στημι</span>]) aquele que zela pelos interesses de outros, defensor, guardião, benfeitor, de divindades; termo importante numa sociedade que atribuía grande importância à beneficência e ao patronato (Soph., Oed. Rex 881, Trach. 208; Cornutus 27 p. 51, 15 <span class=\"greek\">πρ</span>. <span class=\"greek\">κ</span>. <span class=\"greek\">σωτήρ</span>; Heraclit. Sto. 11 p. 18, 9; 38 p. 55, 11; Ael. Aristid. 28, 156 K.=49 p. 542 D.; 33, 2 K.=51 p. 572 D.: <span class=\"greek\">Ἀσκληπιὸς</span> <span class=\"greek\">πρ</span>. <span class=\"greek\">ἡμέτερος</span>; escólio sobre Pind., Isthm. 1, 11c <span class=\"greek\">πρ</span>. <span class=\"greek\">ὁ</span> <span class=\"greek\">θεός</span>; Jos., Ant. 7, 380), de Cristo, em cada caso com <span class=\"greek\">ἀρχιερεύς</span>: 1 Cl 64; <span class=\"greek\">πρ</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">βοηθός</span> 36:1; <span class=\"greek\">προστάτης</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ψυχῶν</span> <span class=\"greek\">ἡμῶν</span> 61:3.—V. artigo seguinte. DELG s.v. <span class=\"greek\">ἴστημι</span>. New Docs 4, 242–44. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0307-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προστάτις, ιδος, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προστάτις</span>, <span class=\"greek\">ιδος</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">προί̈στημι</span>, cf. <span class=\"greek\">προστάτης</span>; Cornutus 20 p. 37, 20; Lucian, Bis Accus. 29 <span class=\"greek\">θεὰ</span> <span class=\"greek\">προστάτις</span> <span class=\"greek\">ἑαυτῶν</span>; Cass. Dio 42, 39 al.; PGM 36, 338; também ref. de pap New Docs 4, 243) mulher que exerce uma função de apoio, patrona, benfeitora (a relação sugerida pelo termo <span class=\"greek\">πρ</span>. não deve ser confundida com o sistema romano de patrono e cliente, que era de outra natureza e estranho à tradição grega [v. JTouloumakos, Her 116, ’88, 304–24]) <span class=\"greek\">προστάτις</span> <span class=\"greek\">πολλῶν</span> <span class=\"greek\">ἐγενήθη</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐμοῦ</span> <span class=\"greek\">αὐτοῦ</span> ela demonstrou ser de grande auxílio a muitos, inclusive a mim mesmo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:2</a> (Ltzm., Hdb. ad loc. O masc. <span class=\"greek\">προστάτης</span> adquiriu sentido técnico e é encontrado com este sentido tanto em círculos religiosos israelitas [Schürer III, 102] como politeístas [OGI 209; SIG 1109, 13; CIG I, 126; GHeinrici, ZWT 19, 1876, 516ff.—EZiebarth, Das griech. Vereinswesen 1896, índice s.v.; Poland, Gesch., índice s.v.; WOtto, Priester u. Tempel im hellenist. Ägypten II 1908 p. 75, 1]).—V. artigo anterior. Sobre mulheres como benfeitoras, v. RvanBremen, em Images of Women in Antiquity, ed. ACameron/AKuhrt ’83, 223–42; COsiek, Women in the Ancient Mediterranean World: BR 39, ’94, 57–61 (NT). New Docs 4, 242–44. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0307-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προστίθημι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προστίθημι</span> (Hom.+) imperf. 3.ª sg. <span class=\"greek\">προσετίθει</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.47\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:47</a>; fut. <span class=\"greek\">προσθήσω</span>; 1.º aor. <span class=\"greek\">προσέθηκα</span>; 2.º aor. subj. <span class=\"greek\">προσθῶ</span>, imper. <span class=\"greek\">πρόσθες</span>, inf. <span class=\"greek\">προσθεῖναι</span>, part. <span class=\"greek\">προσθείς</span>; perf. 2.ª sg. <span class=\"greek\">προστέθεικας</span> 3 Km 10:7. Médio: fut. <span class=\"greek\">προσθήσομαι</span> LXX; 2.º aor. <span class=\"greek\">προσεθέμην</span>. Pass.: imperf. 3.ª pl. <span class=\"greek\">προσετίθεντο</span>; 1.º fut. <span class=\"greek\">προστεθήσομαι</span>; 1.º aor. <span class=\"greek\">προσετέθην</span>.</p><p class=\"entry-text\">① acrescentar a algo que já está presente ou existe, acrescentar, juntar a</p><p class=\"entry-text\">ⓐ de coisas que são acrescentadas a algo já presente: uso absoluto (oposto a <span class=\"greek\">ἀφαιρεῖν</span>; v. Isocr. 12, 264; Pla., Leg. 5 p. 742d al.; Epict. 1, 6, 10; Dt 4:2; 13:1) acrescentar (algo) B 19:11; D 4:13. Pass. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:24</a>. <span class=\"greek\">τὶ</span> algo Hs 5, 3, 3; D 11:2. <span class=\"greek\">τῇ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">παιδὶ</span> <span class=\"greek\">προσετίθεντο</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">μῆνες</span> <span class=\"greek\">αὐτῆς</span> lit. os meses eram acrescentados à sua criança (=a filha [Maria] dela [Ana] crescia mês a mês) GJs 7:1. Do acréscimo de uma palavra, frase etc. (Demosth. et al.; Just., D. 55, 1; Mitt-Wilck. II/2, 372 V, 11 [a declaração segue em discurso direto]; PStras 41, 21) 1 Cl 8:2, de um acréscimo a um documento escrito (EpArist 26; Jos., Ant. 1, 17); <span class=\"greek\">ῥήματα</span> Hv 2, 4, 2. Da fé <span class=\"greek\">πρόσθες</span> <span class=\"greek\">ἡμῖν</span> <span class=\"greek\">πίστιν</span> aumenta nossa fé <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:5</a> (outros colocariam isto em 2 abaixo.) Pass. (<span class=\"greek\">ὁ</span> <span class=\"greek\">νόμος</span>) <span class=\"greek\">προσετέθη</span> (a lei) foi acrescentada à promessa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:19</a>.—<span class=\"greek\">πρ</span>. <span class=\"greek\">λόγον</span> <span class=\"greek\">τινί</span> dirigir outra mensagem a alguém (Dionys. Hal. 6, 88, 3; 8, 9, 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.19\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:19</a> (<span class=\"greek\">παραιτέομαι</span> 1b).—<span class=\"greek\">τί</span> <span class=\"greek\">τινι</span> algo a algo <span class=\"greek\">ταῖς</span> <span class=\"greek\">ἁμαρτίαις</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ἀσελγείας</span> Hv 2, 2, 2.—É frequentemente usado somente com dat., a partir do qual o acus. é facilmente suprido: acrescentar a, aumentar <span class=\"greek\">πρ</span>. <span class=\"greek\">ταῖς</span> <span class=\"greek\">ἁμαρτίαις</span> <span class=\"greek\">ὑμῶν</span> Hv 5:7; cf. m 4, 3, 7; 12, 6, 2; Hs 6, 1, 4; 6, 2, 3; 8, 11, 3. <span class=\"greek\">προσθεῖναι</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">δρόμῳ</span> <span class=\"greek\">σου</span> prosseguir em teu percurso IPol 1:2.—<span class=\"greek\">τὶ</span> <span class=\"greek\">ἐπί</span> <span class=\"greek\">τι</span> algo a algo (4 Km 20:6; PsSol 3:10 <span class=\"greek\">ἁμαρτίας</span> <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ἁμαρτίας</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:25</a>. <span class=\"greek\">τὶ</span> <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινι</span> (Sir 3:27) <span class=\"greek\">προσέθηκεν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τοῦτο</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">πᾶσιν</span> acrescentou isto a todos os (seus) outros (delitos) 3:20 (B-D-F §461, 2; Rob. 605).</p><p class=\"entry-text\">ⓑ de pessoas acrescentadas a um grupo já existente ou ligadas a um indivíduo, ao qual doravante pertencem: acrescentar, associar (Diod S 5, 45, 3) <span class=\"greek\">πρ</span>. <span class=\"greek\">τινὰ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἐκκλησίᾳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.47\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:47</a> v.l. O mesmo dat. deve ser suprido no texto preferido pelas edições críticas nesta passagem; igualmente vv. 41 e 5:14 (se <span class=\"greek\">τῷ</span> <span class=\"greek\">κυρίῳ</span> deve ser ligado aqui a <span class=\"greek\">πιστεύοντες</span>, outro dat. deve ser suprido com <span class=\"greek\">προσετίθεντο</span>).—<span class=\"greek\">προστίθεσθαι</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κυρίῳ</span> ser conduzido ao Senhor 11:24. Também 5:14 (v. acima), caso <span class=\"greek\">τῷ</span> <span class=\"greek\">κυρ</span>. aqui pertença a <span class=\"greek\">προσετίθ</span>. (<span class=\"greek\">προστίθεσθαι</span> dificilmente significa ‘ligar-se a’ como em Demosth. 18, 39 al.; 1 Macc 2:43; Jos., Vi. 87, 123).—De um falecido <span class=\"greek\">πρ</span>. <span class=\"greek\">πρὸς</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">πατέρας</span> <span class=\"greek\">αὐτοῦ</span> ser reunido a seus antepassados (Judg 2:10; 4 Km 22:20; 1 Macc 2:69; ViMal 4 [p. 89, 8 Sch.]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.36\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:36</a>.</p><p class=\"entry-text\">ⓒ De acordo com o uso hebr. (mas v. Helbing p. iv, contradito por AWifstrand, SvTK 16, ’40, 257), os advérbios novamente, além disso e expressões semelhantes são parafraseados com <span class=\"greek\">πρ</span>. (B-D-F §392, 2; 419, 4; 435a; Mlt-H. 445f). <span class=\"greek\">προσθεὶς</span> <span class=\"greek\">εἶπεν</span> <span class=\"greek\">παραβολήν</span> contou novamente uma parábola, ou passou a contar uma parábola <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:11</a>; Ox 1081,10 (para a reconstituição: <span class=\"greek\">προ</span>[<span class=\"greek\">σθεὶς</span> <span class=\"greek\">ε</span>]<span class=\"greek\">ἶπεν</span> v. Wessely, PatrOr 18, 1924, 494, 10=Otero I 83) (Gen 38:5 <span class=\"greek\">προσθεῖσα</span> <span class=\"greek\">ἔτεκεν</span> <span class=\"greek\">υἱόν</span>). <span class=\"greek\">οὐ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">προσθῶ</span> <span class=\"greek\">πεῖν</span> jamais tornarei a beber <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:25</a> v.l. <span class=\"greek\">προσθήσω</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἐπερωτῆσαι</span> Hm 4, 3, 1. Encontra-se geralmente na voz média, seguido de inf. (Gen 8:12; Ex 9:34 <span class=\"greek\">Φαραὼ</span> <span class=\"greek\">προσέθετο</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἁμαρτάνειν</span>; 1 Km 18:29) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:11f</a>. <span class=\"greek\">προσέθετο</span> <span class=\"greek\">συλλαβεῖν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">Πέτρον</span> passou a mandar prender também Pedro <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:3</a> (cf. AcJ 2 [Aa II/1, 151, 14]). V. 1 Cl 12:7; B 2:5 (Is 1:13).</p><p class=\"entry-text\">② acrescentar como benefício, prover, dar, conceder, fazer (X., Cyr. 2, 2, 18 <span class=\"greek\">τὰς</span> <span class=\"greek\">τιμὰς</span> <span class=\"greek\">ἑκάστῳ</span>; PRyl 153, 27) <span class=\"greek\">τινί</span> <span class=\"greek\">τι</span> algo a alguém <span class=\"greek\">πρόσθες</span> <span class=\"greek\">ἡμῖν</span> <span class=\"greek\">πίστιν</span> concede-nos fé <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:5</a>. Com dat. de coisa <span class=\"greek\">προσέθηκε</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἀμπελῶνι</span> <span class=\"greek\">ἔργον</span> <span class=\"greek\">καλόν</span> fez bom trabalho na vinha Hs 5, 2, 7.—Pass. <span class=\"greek\">ταῦτα</span> <span class=\"greek\">προστεθήσεται</span> <span class=\"greek\">ὑμῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:33</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:31</a>. V. Agr 10ab (Unknown Sayings, 87–89).—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0307-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρόστιμον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πρόστιμον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (Hippocr.; Polyb. 1, 17, 11; Diod S 1, 65, 3; Lucian, Anach. 21; Plut., Solon 91 [23, 2]; ins, pap; 2 Macc 7:36; Jos., Ant. 4, 248. Primariamente ‘algo que é pago adicionalmente’, p. ex. ‘multa’) pena <span class=\"greek\">θάνατον</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πρόστιμον</span> <span class=\"greek\">ἔχειν</span> incorrer na pena de morte 1 Cl 41:3.—DELG s.v. <span class=\"greek\">τιμή</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0307-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προστρέχω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προστρέχω</span> 2.º aor. <span class=\"greek\">προσέδραμον</span> (Aristoph., X., Pla. et al.; POxy 247, 12 [não literal]; LXX; ApcEsdr 7:15 p. 33, 3 Tdf.; Jos., Ant. 7, 249, Vi. 140; Just., D. 105, 5) correr para ou em direção a, aproximar-se correndo (de); exceto pela v.l. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.16\" target=\"_blank\" rel=\"noopener noreferrer\">J 20:16</a>, é usado em nossa literatura somente no part., combinado com outro verbo (Menand., Per. 155 S. [35 Kö.]; Num 11:27; Tob 11:9 BA; Jos., Bell. 1, 662; TestNapht 5:2) <span class=\"greek\">προστρέχοντες</span> <span class=\"greek\">ἠσπάζοντο</span> <span class=\"greek\">αὐτόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:15</a>. Cf. 10:17; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.30\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:30</a>; Hs 9, 6, 2.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0307-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσφάγιον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προσφάγιον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (de <span class=\"greek\">φαγεῖν</span>, não se deve confundir com o homógrafo derivado de <span class=\"greek\">προσφάζω</span> ‘sacrificar previamente’; ‘um acompanhamento’ comido com pão [Proverbia Aesopi 98 P. <span class=\"greek\">πρ</span>. ao lado de <span class=\"greek\">ἄρτος</span>; POxy 498, 33; 39 <span class=\"greek\">ἄρτον</span> <span class=\"greek\">ἕνα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">προσφάγιον</span>; 736, 46; 89; 739, 7; 10; 12; 14; BGU 916, 22; PGrenf II, 77, 21; OGI 484, 26. Segundo Moeris e Hesychius equivale a <span class=\"greek\">ὄψον</span>. Mas esta última palavra, assim como seu dim. <span class=\"greek\">ὀψάριον</span> (v. esse artigo), frequentemente equivale simplesmente a ‘peixe’]) peixe (para comer) <span class=\"greek\">μή</span> <span class=\"greek\">τι</span> <span class=\"greek\">προσφάγιον</span> <span class=\"greek\">ἔχετε</span>; não tendes peixe para comer, não é? ou pescastes algo para comer? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.5\" target=\"_blank\" rel=\"noopener noreferrer\">J 21:5</a> (o contexto narrativo contrasta a falta de êxito dos discípulos em prover uma refeição com o papel do Senhor como cozinheiro, vv. 9–13).—DELG s.v. <span class=\"greek\">φαγεῖν</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0307-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρόσφατος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πρόσφατος</span>, <span class=\"greek\">ον</span> (Hom. et al.; sobre a formação v. Boisacq s.v.) novo, recente (Aeschyl. et al.; Michel 1501, 24 [103/102 a.C.]; POxy 1088, 25; LXX; Jos., Ant. 1, 264. V. Phryn. p. 374 Lob.) Hs 9, 2, 2 (oposto a <span class=\"greek\">παλαιός</span>). Também no sentido ‘não existente anteriormente’ (cf. Eccl 1:9 <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔστιν</span> <span class=\"greek\">πᾶν</span> <span class=\"greek\">πρόσφατον</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἥλιον</span>; Ps 80:10) <span class=\"greek\">ὁδός</span> Hb l0:20.—DELG s.v. <span class=\"greek\">θείνω</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0307-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσφάτως</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προσφάτως</span> adv. de <span class=\"greek\">πρόσφατος</span>, de tempo: recentemente (Machon [III a.C.] v. 364, em Athen. 13, 581e; Polyb. 3, 37, 11; Alciphron 4, 14, 2; OGI 315, 23 [164/163 a.C.] <span class=\"greek\">ἐληλυθότι</span> <span class=\"greek\">προσφάτως</span>; UPZ 144, 10 [164 a.C.]; LXX; EpArist 5; Jos., Bell. 1, 127, Ant. 10, 264) em nossa literatura usado com <span class=\"greek\">ἐληλυθὼς</span> <span class=\"greek\">ἀπό</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:2</a>; MPol 4.—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0307-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προσφέρω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προσφέρω</span> imperf. <span class=\"greek\">προσέφερον</span>; fut. <span class=\"greek\">προσοίσω</span> LXX; aor. <span class=\"greek\">προσήνεγκον</span> e <span class=\"greek\">προσήνεγκα</span> (v. B-D-F §81, 2; Rob. 338; 363); perf. <span class=\"greek\">προσενήνοχα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.17\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:17</a>; 1.º aor. pass. <span class=\"greek\">προσηνέχθην</span> (Pind.+).</p><p class=\"entry-text\">① trazer alguém ou algo a alguém, trazer, ativo e passivo</p><p class=\"entry-text\">ⓐ trazer (a), com acus. de pessoa <span class=\"greek\">τινά</span> <span class=\"greek\">τινι</span> trazer alguém a alguém, enfermos a Jesus ou a seus discípulos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:24</a>; 8:16; 9:2, 32; 12:22 v.l. (em lugar do pass.); 14:35; 17:16. O acus. está ausente, mas é facilmente suprido <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:4</a>. Crianças a Jesus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:13a</a>; cf. b v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:15</a>. Pass. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:13</a>. Levar alguém perante juiz, rei etc. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:14</a>; cf. 12:11 v.l. (em lugar de <span class=\"greek\">εἰσφέρωσιν</span>). Pass. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:24</a>.</p><p class=\"entry-text\">ⓑ trazer (a), com acus. de coisa</p><p class=\"entry-text\"><span class=\"greek\">α</span>. trazer (a), oferecer (Iren. 1, 13, 2 [Harv. I, 117, 3]; Did., Gen. 123, 25) <span class=\"greek\">τί</span> <span class=\"greek\">τινι</span> algo (a) alguém <span class=\"greek\">προσήνεγκαν</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">δηνάριον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:19</a>. V. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:18</a>; 1 Cl 43:2. Sem dat., que é suprido pelo contexto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:20</a>; Hs 8, 1, 12.—Especialmente trazer a alguém algo para beber (Menand., Georg. 61 S. e Kö. <span class=\"greek\">φαγεῖν</span> <span class=\"greek\">πρ</span>.; Jos., Bell. 1, 488, Ant. 4, 72 <span class=\"greek\">οἶνον</span> <span class=\"greek\">προσφέρεσθαι</span>=‘tomar vinho’, Vi. 225) <span class=\"greek\">ὄξος</span> <span class=\"greek\">προσφέροντες</span> <span class=\"greek\">αὐτῷ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:36</a>. Cf. <span class=\"greek\">σπόγγον</span> <span class=\"greek\">μεστὸν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὄξους</span> … <span class=\"greek\">προσήνεγκαν</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">στόματι</span> levaram uma esponja cheia de vinagre à sua boca <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.29\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:29</a>. Sem acus. de coisa GJs 18:2 (codd.).—Sem dat. <span class=\"greek\">ὕδωρ</span> … <span class=\"greek\">προσήνεγκεν</span> (Paulo) então trouxe água (depois de distribuir o pão eucarístico) AcPl Ha 4, 4.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. <span class=\"greek\">τὴν</span> <span class=\"greek\">χεῖρα</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">παιδίῳ</span> estender (tua) mão à criança GJs 20:3 (codd.).</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. fig., de partidarismo <span class=\"greek\">ἥττονα</span> <span class=\"greek\">ἁμαρτίαν</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">προσήνεγκεν</span> tornou-vos menos culpados, lit. ‘(aquele facciosismo) trouxe sobre vós menos pecado’ 1 Cl 47:4.</p><p class=\"entry-text\">② apresentar algo a alguém, trazendo-o, trazer, oferecer, apresentar, de ofertas, presentes etc. (Simplicius In Epict. p. 93, 41 Düb. <span class=\"greek\">τὰς</span> <span class=\"greek\">ἀπαρχάς</span> [<span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span>]; frequentemente LXX; Jos., Bell. 3, 353, Ant. 3, 231).</p><p class=\"entry-text\">ⓐ lit. <span class=\"greek\">τὶ</span> algo, com ou sem dat. de pessoa (de orações Orig., C. Cels. 8, 13, 21) <span class=\"greek\">δῶρον</span>, <span class=\"greek\">δῶρα</span> (Jos., Ant. 6, 67), dos presentes trazidos pelos magos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:11</a> (v. Ps 71:10; sobre a qualidade de tais presentes cf. Aristot., Fgm. 101 <span class=\"greek\">οὐθὲν</span> <span class=\"greek\">κολοβὸν</span> <span class=\"greek\">προσεφέρομεν</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τούς</span> <span class=\"greek\">θεούς</span>=não oferecemos nada de qualidade inferior aos deuses); de ofertas sacrificiais 5:23f; 8:4; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.3\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:3f</a>; 9:9 (pass.); GJs 1:1f; 5:1; 1 Cl 44:4. <span class=\"greek\">θυσίαν</span>, <span class=\"greek\">θυσίας</span> (EpArist 170b; Jos., Ant. 8, 118; Just., D. 41, 2 al. <span class=\"greek\">λογικὴν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἄκαπνον</span> <span class=\"greek\">θυσίαν</span> Orig., C. Cels. 7, 1, 15) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.4\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:4</a>; D 14:3 (v. Mal 1:11 e v. 13 v.l.).—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:11</a>; v. vv. 1, 2 (pass.), 8 (pass.); 1 Cl 41, 2a (pass.); PtK 2 p. 14, 21. <span class=\"greek\">σφάγια</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">θυσίας</span> <span class=\"greek\">προσηνέγκατέ</span> <span class=\"greek\">μοι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.42\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:42</a> (Am 5:25). <span class=\"greek\">προσενέγκαι</span> <span class=\"greek\">μοι</span> <span class=\"greek\">ὁλοκαυτώματα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">θυσίας</span> B 2:7 (v. Jer 7:22f); 7:6 (v. Lev 16:7, 9); 8:1 (TestJob 3:3).—<span class=\"greek\">τινά</span> alguém, da oferta de Isaque <span class=\"greek\">προσενήνοχεν</span> (o perf. para denotar o que ‘está escrito’; cf. Mlt 129; 142; 238) <span class=\"greek\">Ἀβραὰμ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Ἰσαὰκ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">μονογενῆ</span> <span class=\"greek\">προσέφερεν</span> (imperf., em sentido conativo ou incoativo, porque o sacrifício não foi efetivamente realizado) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.17\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:17</a>. Cf. <span class=\"greek\">Ἰσαὰκ</span> <span class=\"greek\">προσενεχθεὶς</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">θυσιαστήριον</span> B 7:3b (sobre <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">θυς</span>. cf. 1 Esdr 8:15). <span class=\"greek\">προσήνεγκεν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">παῖδα</span> <span class=\"greek\">Ἰωακεὶμ</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἱερεῦσιν</span> GJs 6:2ab (cf. <span class=\"greek\">προσάγω</span>). De Jesus <span class=\"greek\">ἑαυτὸν</span> <span class=\"greek\">πρ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.27\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:27</a> v.l.; cf. 9:14 (<span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span>); v. 25. <span class=\"greek\">πρ</span>. <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">σφαγήν</span> B 8:2b. Pass. <span class=\"greek\">ὁ</span> <span class=\"greek\">Χριστὸς</span> <span class=\"greek\">προσενεχθείς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.28\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:28</a>; aqui a finalidade é indicada por <span class=\"greek\">εἰς</span> <span class=\"greek\">τό</span> seguido de inf. Em outros lugares a finalidade é expressa por meio de outras preposições: <span class=\"greek\">πρ</span>. (<span class=\"greek\">τι</span>) <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span> (Lev 16:9; Job 1:5) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.44\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:44</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:14</a>. <span class=\"greek\">περὶ</span> <span class=\"greek\">αὐτοῦ</span> (v.l. <span class=\"greek\">ἑαυτοῦ</span>) <span class=\"greek\">προσφέρειν</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">ἁμαρτιῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5:3</a>. Também <span class=\"greek\">ὑπέρ</span> <span class=\"greek\">τινος</span> (1 Macc 7:33) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5:1</a>; 9:7; 10:12; B 7:5. Pass. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:26</a>; B 7:4 (citação da ‘Escritura’ de origem desconhecida). Com duplo acus. oferecer alguém/algo como <span class=\"greek\">θυσίαν</span> sacrifício 1 Cl 10:7; B 7:3a (com <span class=\"greek\">ὑπέρ</span> <span class=\"greek\">τινος</span>). <span class=\"greek\">πρ</span>. <span class=\"greek\">τινί</span> sacrificar a alguém Dg 3:3. Uso absoluto: fazer uma oferta, sacrificar B 8:2a. <span class=\"greek\">ὀρθῶς</span> 1 Cl 4:4 (Gen 4:7). <span class=\"greek\">αἷς</span> <span class=\"greek\">δοκεῖτε</span> <span class=\"greek\">τιμαῖς</span> <span class=\"greek\">προσφέρειν</span> pelas honras que pensais oferecer(-lhes) Dg 2:8. Pass. 1 Cl 41:2b. O part. pres. empregado como subst. <span class=\"greek\">τὸ</span> <span class=\"greek\">προσφερόμενον</span> a oferta 41:2c.—NSnaith, The Sin-Offering and Guilt-Offering, VetusT 15, ’65, 73–80.</p><p class=\"entry-text\">ⓑ fig. (v. BGU 1024 VII, 25 de uma moça pobre <span class=\"greek\">ζῶσα</span> <span class=\"greek\">προσεφέρετο</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">βουλομένοις</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">νεκρά</span>=‘ela se oferecia’) o ato de matar cristãos será considerada pelos judeus como <span class=\"greek\">λατρείαν</span> <span class=\"greek\">προσφέρειν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.16.2\" target=\"_blank\" rel=\"noopener noreferrer\">J 16:2</a> (v. <span class=\"greek\">ἀποκτείνω</span> 1a). <span class=\"greek\">δεήσεις</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἱκετηρίας</span> <span class=\"greek\">πρ</span>. <span class=\"greek\">πρὸς</span> (<span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5:7</a> (Achilles Tat. 7:1 <span class=\"greek\">προσφέρειν</span> <span class=\"greek\">δέησιν</span>; JosAs 12:7 <span class=\"greek\">τὴν</span> <span class=\"greek\">δέησίν</span> <span class=\"greek\">μου</span>; Jos., Bell. 3, 353 <span class=\"greek\">προσφέρει</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span> <span class=\"greek\">εὐχήν</span>; Mel., HE 4, 26, 6 <span class=\"greek\">δέησιν</span>).—<span class=\"greek\">ἁμαρτίαν</span> 1 Cl 47:4; <span class=\"greek\">δῶρα</span> 1 Cl 44:4.</p><p class=\"entry-text\">③ comportar-se para com alguém ou tratar alguém de determinada maneira, lidar com, tratar, pass. em sentido ativo, com dat. de pessoa (assim frequentemente Thu.+; Diod S 14, 90, 3; Aelian, VH 12, 27; Herodian 1, 13, 7; Philo, Ebr. 69, De Jos. 47; Jos., Bell. 7, 254; 263; OGI 456, 64; SIG 807, 13 [54 d.C.]; PLond 1912, 65 [41 d.C.]) <span class=\"greek\">ὡς</span> <span class=\"greek\">υἱοῖς</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">προσφέρεται</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:7</a>.—M-M. EDNT. TW.</p></section></article>"};
